{% set a = states.sensor.weather_ahead.attributes if states.sensor.weather_ahead is not none else {} %}
{% set sc = a.get('scene') if a.get('scene') in fx else 'cloudy' %}
{% set dn = 'day' if is_state('sun.sun', 'above_horizon') else 'night' %}
{% set words = {'clear-night': 'clear', 'sunny': 'sunny', 'partlycloudy': 'partly cloudy', 'cloudy': 'cloudy', 'fog': 'fog', 'rainy': 'rain', 'pouring': 'heavy rain', 'lightning': 'thunder', 'lightning-rainy': 'thunderstorms', 'hail': 'hail', 'snowy': 'snow', 'snowy-rainy': 'sleet', 'windy': 'windy', 'windy-variant': 'windy', 'exceptional': 'unusual weather'} %}
{% set ahead = words.get(states('sensor.weather_ahead')) %}
{% set ahead = 'clear' if ahead == 'sunny' and dn == 'night' else ahead %}
ha-card {
  position: relative; overflow: hidden; isolation: isolate;
  --primary-text-color: #fff;
  --secondary-text-color: rgba(255,255,255,.88);
  color: #fff;
  text-shadow: 0 1px 4px rgba(0,0,0,.75);
}
ha-card > * { position: relative; z-index: 2; }
{{ fx[sc] | replace('DN', dn) }}
@keyframes wx-drift { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@keyframes wx-flash { 0%, 86%, 89%, 92%, 100% { filter: brightness(1); } 87% { filter: brightness(2.4); } 90.5% { filter: brightness(1.9); } }
@media (prefers-reduced-motion: reduce) { ha-card::before, ha-card::after { animation: none !important; } }
{% if ahead %}.name { font-size: 0 !important; }
.name::after { content: 'Next 3 h: {{ ahead }}'; font-size: var(--ha-font-size-m, 14px); }{% endif %}

filter.template:
{%- set word = {'moisture': 'Water leak', 'smoke': 'Smoke', 'gas': 'Gas', 'carbon_monoxide': 'Carbon monoxide', 'safety': 'Safety alarm'} -%}
{%- set ns = namespace(l=[]) -%}
{%- for s in states.binary_sensor | selectattr('attributes.device_class','defined') | selectattr('attributes.device_class','in', word.keys() | list) | selectattr('state','eq','on') -%}
{%- if s.entity_id != 'binary_sensor.any_safety_alarm' -%}
{%- set ns.l = ns.l + [{'type': 'custom:button-card', 'template': 'vg_stat', 'entity': s.entity_id, 'name': word[s.attributes.device_class] ~ ' — ' ~ (area_name(s.entity_id) if area_id(s.entity_id) else s.name), 'grid_options': {'columns': 12, 'rows': 1}}] -%}
{%- endif -%}
{%- endfor -%}
{{ ns.l }}

{%- set ns = namespace(l=[]) -%}
{%- for e in states('sensor.any_safety_sensor_silent').split(', ') if e not in ['none', 'unavailable', 'unknown', ''] -%}
{%- set ns.l = ns.l + [{'type': 'custom:button-card', 'template': 'vg_stat', 'entity': e, 'name': 'Not reporting — ' ~ (state_attr(e, 'friendly_name') or e) ~ (' (' ~ area_name(e) ~ ')' if area_name(e) else ''), 'tap_action': {'action': 'more-info'}, 'grid_options': {'columns': 12, 'rows': 1}}] -%}
{%- endfor -%}
{{ ns.l }}

{%- set ns = namespace(l=[]) -%}
{%- for e in states('sensor.any_low_battery').split(', ') if e not in ['none', 'unavailable', 'unknown', ''] -%}
{%- if e.startswith('+') -%}
{%- set ns.l = ns.l + [{'type': 'markdown', 'content': e}] -%}
{%- else -%}
{%- set ns.l = ns.l + [{'type': 'custom:button-card', 'template': 'vg_stat', 'entity': e, 'name': 'Battery low — ' ~ ((state_attr(e, 'friendly_name') or e) | replace(' Battery', '')), 'tap_action': {'action': 'more-info'}, 'grid_options': {'columns': 12, 'rows': 1}}] -%}
{%- endif -%}
{%- endfor -%}
{{ ns.l }}

cards.content:
{% set ns = namespace(mould=[], health=[], air=[]) %}{% set rooms = [('Living room','living_room'),('Office','office'),('Bedroom','bedroom'),('Kids room 1','kid1'),('Kids room 2','kid2')] %}{% set page = {'living_room': 'living-room', 'office': 'guest-room', 'bedroom': 'bedroom', 'kid1': 'kid1', 'kid2': 'kid2'} %}{% for name, r in rooms %}{% set t = states('sensor.climate_temp_' ~ r) | float(-99) %}{% set h = states('sensor.climate_humidity_' ~ r) | float(-1) %}{% if t > -90 and h >= 0 %}{% set g = (17.27 * t / (237.7 + t)) + log(h / 100) %}{% set dp = 237.7 * g / (17.27 - g) %}{% set sp = t - dp %}{% if h >= 70 %}{% set ns.mould = ns.mould + ['[**' ~ name ~ '**](/lovelace/' ~ page.get(r, 'home') ~ ') ' ~ h ~ '% RH — mould grows above 70%'] %}{% elif h >= 65 %}{% set ns.mould = ns.mould + ['[**' ~ name ~ '**](/lovelace/' ~ page.get(r, 'home') ~ ') ' ~ h ~ '% RH — drifting toward mould territory'] %}{% endif %}{% if sp < 3 %}{% set ns.mould = ns.mould + ['[**' ~ name ~ '**](/lovelace/' ~ page.get(r, 'home') ~ ') only ' ~ sp | round(1) ~ ' °C above its dew point — condensation on any cooler surface'] %}{% endif %}{% if h < 30 %}{% set ns.health = ns.health + ['[**' ~ name ~ '**](/lovelace/' ~ page.get(r, 'home') ~ ') ' ~ h ~ '% RH — dry enough to irritate airways'] %}{% endif %}{% if t < 16 %}{% set ns.health = ns.health + ['[**' ~ name ~ '**](/lovelace/' ~ page.get(r, 'home') ~ ') ' ~ t | round(1) ~ ' °C — cold enough to be a health risk, not just uncomfortable'] %}{% endif %}{% endif %}{% endfor %}{% for s in states.sensor | selectattr('attributes.device_class','defined') | selectattr('attributes.device_class','eq','carbon_dioxide') | list %}{% if s.state | float(0) >= 1400 %}{% set ns.air = ns.air + ['**' ~ s.name ~ '** ' ~ s.state ~ ' ppm CO₂ — ventilate'] %}{% elif s.state | float(0) >= 1000 %}{% set ns.air = ns.air + ['**' ~ s.name ~ '** ' ~ s.state ~ ' ppm CO₂ — stuffy'] %}{% endif %}{% endfor %}{% for s in states.sensor | selectattr('attributes.device_class','defined') | selectattr('attributes.device_class','eq','pm25') | rejectattr('entity_id','search','openweathermap') | list %}{% if s.state | float(0) >= 25 %}{% set ns.air = ns.air + ['**' ~ s.name ~ '** ' ~ s.state ~ ' µg/m³ PM2.5'] %}{% endif %}{% endfor %}{% set aqi = states('sensor.outside_openweathermap_air_quality_index') | int(0) %}{% if aqi >= 4 %}{% set ns.air = ns.air + ['Outdoor air quality **' ~ aqi ~ '/5** — keep windows shut; do not ventilate to cool'] %}{% endif %}{% if ns.mould %}🦠 **Damp / mould risk**
{% for x in ns.mould %}- {{ x }}
{% endfor %}
{% endif %}{% if ns.health %}🫁 **Health**
{% for x in ns.health %}- {{ x }}
{% endfor %}
{% endif %}{% if ns.air %}🌫️ **Air quality**
{% for x in ns.air %}- {{ x }}
{% endfor %}{% endif %}
